@guest
<div id="auth-gate" class="auth-gate" aria-hidden="true"><div class="auth-gate-scrim" onclick="akCloseAuthGate()"></div><div class="auth-gate-card"><button class="auth-gate-close" onclick="akCloseAuthGate()">×</button><div class="auth-gate-icon"><x-icon name="lock" :size="23"/></div><div style="font-size:20px;font-weight:700">Доступ после входа</div><div id="auth-gate-copy" style="font-size:13px;line-height:1.6;color:var(--text-faint);margin:8px 0 20px">Войдите или создайте аккаунт, чтобы пользоваться этой функцией.</div><div style="display:grid;gap:9px"><a href="{{ route('login') }}" class="btn-accent">Войти в аккаунт</a><a href="{{ route('register') }}" class="btn-ghost">Создать аккаунт</a></div><div style="font-size:10px;color:var(--text-faint);margin-top:15px">Регистрация занимает меньше минуты</div></div></div>
<style>.auth-gate{position:fixed;inset:0;z-index:200;display:grid;place-items:center;opacity:0;visibility:hidden;transition:.2s}.auth-gate.show{opacity:1;visibility:visible}.auth-gate-scrim{position:absolute;inset:0;background:var(--scrim);backdrop-filter:blur(5px)}.auth-gate-card{position:relative;width:min(390px,calc(100vw - 28px));padding:30px;border-radius:20px;background:var(--surface);border:1px solid var(--border);text-align:center;box-shadow:0 30px 80px rgba(0,0,0,.35);transform:translateY(10px) scale(.98);transition:.2s}.auth-gate.show .auth-gate-card{transform:none}.auth-gate-close{position:absolute;right:13px;top:11px;border:0;background:none;color:var(--text-faint);font-size:22px}.auth-gate-icon{width:54px;height:54px;border-radius:16px;display:grid;place-items:center;margin:0 auto 16px;background:var(--accent-soft);color:var(--accent)}</style>
<script>function akOpenAuthGate(feature){const copy={wishlist:'Чтобы сохранять товары в избранном, войдите или создайте аккаунт.',compare:'Чтобы сравнивать характеристики товаров, войдите или зарегистрируйтесь.',cart:'Чтобы добавлять товары в корзину и оформлять заказ, войдите в аккаунт.',review:'Чтобы писать отзывы и ответы, необходимо войти.'};document.getElementById('auth-gate-copy').textContent=copy[feature]||copy.cart;document.getElementById('auth-gate').classList.add('show');document.body.style.overflow='hidden'}function akCloseAuthGate(){document.getElementById('auth-gate')?.classList.remove('show');document.body.style.overflow=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')akCloseAuthGate()})</script>
@endguest
